// function tierDiscount(amount)
// < 1000: 5%, 1000-4999: 10%, 5000-9999: 15%, >=10000: 20%
// Discounted amount return karo

solution:
function tierDiscount(amount) {
  let discount
  if (amount < 1000) discount = 0.05
  else if (amount < 5000) discount = 0.10
  else if (amount < 10000) discount = 0.15
  else discount = 0.20
  return amount - (amount * discount)
}
